        // because it inherits the base contract which allows any caller.
        // The buggy contract adds onlyOptimisticAsserter modifier to assertionResolvedCallback, causing revert.

        // Call assertionResolvedCallback directly — should succeed in reference, revert in buggy
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertionResolvedCallback(bytes32,bool)", assertionId, true));

        // To isolate the mutation, we need to call assertionDisputedCallback first which triggers the change
        // Actually the mutation is in assertionDisputedCallback — but the bug is that assertionResolvedCallback gets the incorrect modifier.
